187	      body: `Issue ${payload.issueId} is now yours`,
188	      href: `/issues/${payload.issueId}`,
189	      actorId: payload.actorId,
190	    });
191	  });
192	
193	  subscribe("issue.overdue", async (payload) => {
194	    if (payload.assigneeId === null) return;
195	    await notify(payload.orgId, "issue_overdue", [payload.assigneeId], {
196	      title: "An issue is overdue",
197	      body: `Issue ${payload.issueId} was due ${payload.dueAt}`,
198	      href: `/issues/${payload.issueId}`,
199	      actorId: null,
200	    });
201	  });
202	
203	  subscribe("comment.created", async (payload) => {
204	    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
205	    const watchers = issue
206	      ? [issue.authorId, ...(issue.assigneeId ? [issue.assigneeId] : [])]
207	      : [];
208	
209	    await notify(payload.orgId, "comment_created", watchers, {
210	      title: "New comment",
211	      body: `A comment was added to issue ${payload.issueId}`,
212	      href: `/issues/${payload.issueId}`,
213	      actorId: payload.actorId,
214	    });
215	
216	    if (payload.mentionedUserIds.length > 0) {
217	      await notify(
218	        payload.orgId,
219	        "comment_mention",
220	        payload.mentionedUserIds,
221	        {
222	          title: "You were mentioned",
223	          body: `You were mentioned on issue ${payload.issueId}`,
224	          href: `/issues/${payload.issueId}`,
225	          actorId: payload.actorId,
226	        },
227	      );
228	    }
229	  });
230	
231	  subscribe("member.joined", async (payload) => {
232	    const org = requireFound(
233	      await orgRepo.findOrgById(payload.orgId),
234	      "Organization",
235	      payload.orgId,
236	    );
237	    await notify(payload.orgId, "member_joined", [org.ownerId], {
238	      title: "A new member joined",
239	      body: `${payload.userId} joined as ${payload.role}`,
240	      href: "/settings/members",
241	      actorId: payload.userId,
242	    });
243	  });
244	}
245	
246	registerFanOut();
